/**
 * Background music. Default 'local' source: soundtrack exported from the player's own ROM.
 * Alternative 'original' source: chiptune compositions generated by the game itself.
 * One playback at a time, crossfades, playlists without consecutive repeats. Audio starts on the first user gesture.
 */
import type { MusicTrack } from '../data/manifest';
import { COMPOSITIONS, PLAYLISTS, nextTrack, renderBars, type Composition, type MusicContext } from '../systems/compositions';

const FADE_SEC = 1.4;
const BARS_PER_PLAY = 32;
const LOOKAHEAD_SEC = 0.35;

let tracks = new Map<string, MusicTrack>();
let localPools: Record<string, string[]> = {};
let volume = 0.45;
let muted = false;
let unlocked = false;
let source: 'original' | 'local' = 'original';
let context: MusicContext | null = null;
let ctx: AudioContext | null = null;
let master: GainNode | null = null;
let noiseBuf: AudioBuffer | null = null;
let lastId: string | null = null;
let nowPlaying = '';

type Voice = { stop(): void };
let voice: Voice | null = null;

export function initMusic(list: MusicTrack[], contexts: Record<string, string[]> = {}) {
  tracks = new Map(list.map((t) => [t.id, t]));
  localPools = contexts;
  const unlock = () => {
    if (unlocked) return;
    unlocked = true;
    if (context) start(context);
  };
  window.addEventListener('pointerdown', unlock);
  window.addEventListener('keydown', unlock);
}

export function musicUnlocked() { return unlocked; }
export function currentTrack() { return nowPlaying; }

const level = () => (muted ? 0 : volume);

export function setMusicVolume(v: number, mute: boolean) {
  volume = Math.max(0, Math.min(1, v));
  muted = mute;
  if (master && ctx) master.gain.setTargetAtTime(level(), ctx.currentTime, 0.05);
  if (audioEl) audioEl.volume = level();
}

export function setMusicSource(s: 'original' | 'local') {
  if (s === source) return;
  source = s;
  if (context && unlocked) start(context);
}

/** Selects what should be playing. Calling it again with the same context changes nothing. */
export function setMusicContext(c: MusicContext) {
  if (c === context && voice) return;
  context = c;
  if (unlocked) start(c);
}

/**
 * Fix 1.32: each screen family keeps ITS theme and where it was: going back to the menu resumes the menu theme from the
 * same point instead of starting it over (it sounded broken, cut on every screen change).
 */
const contextTrack: Record<string, string> = {};
const positions = new Map<string, number>();

function start(c: MusicContext) {
  if (source === 'local') {
    const pool = (localPools[c] ?? []).filter((t) => tracks.has(t));
    if (nowPlaying && voice && pool.includes(nowPlaying)) return; // screens sharing a track keep it playing instead of restarting it
    const keep = contextTrack[c] && pool.includes(contextTrack[c]) ? contextTrack[c] : null;
    const id = keep ?? nextTrack(pool, lastId, Math.random);
    if (id) { lastId = id; contextTrack[c] = id; playLocal(tracks.get(id)!, c); return; }
  }
  const id = nextTrack(PLAYLISTS[c], lastId, Math.random);
  if (id) { lastId = id; playComposition(COMPOSITIONS.find((x) => x.id === id)!, c); }
}

// ---------------------------------------------------------------- original compositions
function audio() {
  if (!ctx) {
    ctx = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
    master = ctx.createGain();
    master.gain.value = level();
    // soft chain: rolls off the buzzy highs and stops peaks from ever getting harsh
    const tone = ctx.createBiquadFilter();
    tone.type = 'lowpass';
    tone.frequency.value = 1600;
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -24;
    limiter.ratio.value = 12;
    master.connect(tone).connect(limiter).connect(ctx.destination);
    noiseBuf = ctx.createBuffer(1, ctx.sampleRate / 4, ctx.sampleRate);
    const d = noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  }
  if (ctx.state === 'suspended') void ctx.resume();
  return ctx;
}

function playComposition(comp: Composition, c: MusicContext) {
  const a = audio();
  stopCurrent();
  token++;
  nowPlaying = comp.title;
  const bus = a.createGain();
  bus.gain.setValueAtTime(0.0001, a.currentTime);
  bus.gain.exponentialRampToValueAtTime(1, a.currentTime + FADE_SEC);
  bus.connect(master!);
  const events = renderBars(comp, BARS_PER_PLAY);
  const stepSec = 60 / comp.bpm / 4;
  const t0 = a.currentTime + 0.1;
  let next = 0;
  let stopped = false;
  const note = (type: OscillatorType, freq: number, at: number, dur: number, gain: number) => {
    const o = a.createOscillator(), g = a.createGain();
    o.type = type;
    o.frequency.value = freq;
    g.gain.setValueAtTime(gain, at);
    g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
    o.connect(g).connect(bus);
    o.start(at);
    o.stop(at + dur + 0.02);
  };
  const hit = (at: number, dur: number, gain: number, cutoff: number) => {
    const s = a.createBufferSource(), f = a.createBiquadFilter(), g = a.createGain();
    s.buffer = noiseBuf;
    f.type = 'highpass';
    f.frequency.value = cutoff;
    g.gain.setValueAtTime(gain, at);
    g.gain.exponentialRampToValueAtTime(0.0001, at + dur);
    s.connect(f).connect(g).connect(bus);
    s.start(at);
    s.stop(at + dur + 0.02);
  };
  const tick = () => {
    if (stopped) return;
    const horizon = a.currentTime + LOOKAHEAD_SEC;
    while (next < events.length && t0 + events[next].step * stepSec < horizon) {
      const e = events[next++];
      const at = t0 + e.step * stepSec;
      const dur = e.len * stepSec;
      if (e.part === 'lead') note('triangle', e.freq, at, dur * 0.95, 0.05);
      else if (e.part === 'harmony') note('sine', e.freq, at, dur, 0.02);
      else if (e.part === 'bass') note('sine', e.freq, at, dur * 0.9, 0.09);
      else if (e.part === 'kick') note('sine', 70, at, 0.1, 0.09);
      else if (e.part === 'snare') hit(at, 0.06, 0.02, 900);
    }
    if (next >= events.length && a.currentTime > t0 + (events[events.length - 1]?.step ?? 0) * stepSec) {
      // finished its turn: on to the next track of the same playlist, which never repeats this one
      voice = null;
      start(c);
    }
  };
  const timer = window.setInterval(tick, 90);
  tick();
  voice = {
    stop() {
      stopped = true;
      window.clearInterval(timer);
      bus.gain.cancelScheduledValues(a.currentTime);
      bus.gain.setTargetAtTime(0.0001, a.currentTime, FADE_SEC / 4);
      window.setTimeout(() => bus.disconnect(), FADE_SEC * 1500);
    },
  };
}

// ---------------------------------------------------------------- local OST
let audioEl: HTMLAudioElement | null = null;
/** bumped by every new playback: late callbacks of an older track (play() resolving, 'ended') see a stale token and back off */
let token = 0;
const fades = new WeakMap<HTMLAudioElement, number>();

function playLocal(t: MusicTrack, c: MusicContext) {
  stopCurrent();
  const mine = ++token;
  nowPlaying = t.id;
  const el = new Audio(t.src);
  audioEl = el;
  el.volume = 0;
  el.preload = 'auto';
  // resume where this theme was left (Fix 1.32)
  const at = positions.get(t.id);
  if (at) el.addEventListener('loadedmetadata', () => { if (at < (el.duration || Infinity) - 1) el.currentTime = at; }, { once: true });
  el.addEventListener('error', () => { if (mine === token) { voice = null; nowPlaying = ''; delete contextTrack[c]; } }); // a file that fails doesn't block the music
  el.addEventListener('ended', () => {
    if (mine !== token) return;
    positions.delete(t.id);
    if ((localPools[c]?.length ?? 0) > 1 && context === c) { voice = null; nowPlaying = ''; delete contextTrack[c]; start(c); return; } // next theme of the playlist
    el.currentTime = t.loopStartSec ?? 0;
    void el.play().catch(() => undefined);
  });
  void el.play().then(() => { if (mine === token) fade(el, level(), 900); else el.pause(); }).catch(() => undefined);
  voice = {
    stop() {
      if (audioEl === el) audioEl = null;
      if (el.currentTime > 1) positions.set(t.id, el.currentTime);
      fade(el, 0, 500, () => { el.pause(); el.removeAttribute('src'); el.load(); });
    },
  };
}

/** Timer based, not requestAnimationFrame: rAF stops in background tabs and a fade-out would never finish. */
function fade(el: HTMLAudioElement, target: number, ms: number, done?: () => void) {
  window.clearInterval(fades.get(el));
  const from = el.volume, t0 = performance.now();
  const id = window.setInterval(() => {
    const k = Math.min(1, (performance.now() - t0) / ms);
    el.volume = Math.max(0, Math.min(1, from + (target - from) * k));
    if (k < 1) return;
    window.clearInterval(id);
    done?.();
  }, 30);
  fades.set(el, id);
}

// a hidden tab goes quiet and picks up where it was
document.addEventListener('visibilitychange', () => {
  if (!audioEl) return;
  if (document.hidden) audioEl.pause();
  else void audioEl.play().catch(() => undefined);
});

function stopCurrent() {
  voice?.stop();
  voice = null;
}
